<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Integrations\CustomerPolicy;

/** Native saved-order audience; never grants current policy or writer authority. */
final class PolicySavedAudience {
	public const ORDER_SURFACE='customer_order';public const EMAIL_SURFACE='customer_email';
	public function __invoke(\WC_Order$order,string$surface,?\WC_Email$email=null):bool{try{return match($surface){self::ORDER_SURFACE=>null===$email&&$this->authorize_order($order),self::EMAIL_SURFACE=>null!==$email&&$this->authorize_email($order,$email),default=>false};}catch(\Throwable){return false;}}
	public function authorize_order(\WC_Order$order):bool{try{$f=$this->saved_facts($order);if(null===$f||!function_exists('get_current_user_id')){return false;}$actor=$this->id(get_current_user_id(),true);if(null===$actor){return false;}if($f['customer']>0){return$actor>0&&$actor===$f['customer'];}return$this->guest_route($f['id'],$f['key']);}catch(\Throwable){return false;}}
	private function authorize_email(\WC_Order$order,\WC_Email$email):bool{$native=$email->object??null;if(!method_exists($email,'is_customer_email')||true!==$email->is_customer_email()||!$native instanceof \WC_Order||!method_exists($email,'get_recipient')){return false;}$f=$this->saved_facts($order);$e=$this->facts($native);if(null===$f||$f!==$e){return false;}$billing=$this->mailbox($f['billing']);$recipient=$this->mailbox($email->get_recipient());return null!==$billing&&null!==$recipient&&hash_equals(strtolower($billing),strtolower($recipient));}
	private function saved_facts(\WC_Order$order):?array{$facts=$this->facts($order);if(null===$facts||!function_exists('wc_get_order')){return null;}$saved=wc_get_order($facts['id']);if(!$saved instanceof \WC_Order){return null;}$native=$this->facts($saved);return$facts===$native?$native:null;}
	private function facts(\WC_Order$order):?array{$id=$this->id($order->get_id(),false);$customer=$this->id($order->get_customer_id('edit'),true);$key=$order->get_order_key('edit');$billing=$order->get_billing_email('edit');if(null===$id||null===$customer||!$this->key($key)||!is_string($billing)||strlen($billing)>254||1===preg_match('/[\x00-\x1f\x7f]/',$billing)){return null;}return['id'=>$id,'customer'=>$customer,'key'=>$key,'billing'=>$billing];}
	private function guest_route(int$id,string$key):bool{if(!function_exists('get_query_var')||!isset($_GET['key'])||!is_string($_GET['key'])){return false;}$candidate=function_exists('wp_unslash')?wp_unslash($_GET['key']):$_GET['key'];if(!$this->key($candidate)||!hash_equals($key,$candidate)){return false;}$routes=[];if(function_exists('is_order_received_page')&&is_order_received_page()){$routes[]='order-received';}if(function_exists('is_wc_endpoint_url')&&is_wc_endpoint_url('order-pay')){$routes[]='order-pay';}if((function_exists('is_view_order_page')&&is_view_order_page())||(function_exists('is_wc_endpoint_url')&&is_wc_endpoint_url('view-order'))){$routes[]='view-order';}return 1===count($routes)&&$id===$this->id(get_query_var($routes[0],''),false);}
	private function key(mixed$value):bool{return is_string($value)&&''!==$value&&strlen($value)<=256&&1===preg_match('/\A[\x21-\x7e]+\z/D',$value);}
	private function mailbox(mixed$value):?string{if(!is_string($value)||''===$value||strlen($value)>254||1===preg_match('/[\x00-\x20\x7f,;<>]/',$value)||!function_exists('is_email')||false===is_email($value)){return null;}return$value;}
	private function id(mixed$value,bool$zero):?int{if(is_int($value)){return$value>=($zero?0:1)?$value:null;}if(!is_string($value)||1!==preg_match('/\A(?:0|[1-9][0-9]*)\z/D',$value)||strlen($value)>strlen((string)PHP_INT_MAX)||(strlen($value)===strlen((string)PHP_INT_MAX)&&strcmp($value,(string)PHP_INT_MAX)>0)){return null;}$id=(int)$value;return$id>=($zero?0:1)?$id:null;}
}
